layers, head_dim, seq_len, bytes_fp16 = 32, 128, 32_000, 2
query_heads = 32
designs = {"MHA": 32, "GQA-8": 8, "MQA": 1}          # number of KV heads

report = {}
for name, kv_heads in designs.items():
    total = 2 * layers * kv_heads * head_dim * seq_len * bytes_fp16
    report[name] = {
        "cache_gb": round(total / 1e9, 2),
        "saved": f"{(1 - kv_heads / query_heads) * 100:.1f}%",
    }

for name, row in report.items():
    print(f"{name:6} {row}")
